def _resolve_committed_operation(store, policy_store, record, event):
    """Rebuild the terminal response of a committed-but-unfinished operation.

    Runs during startup recovery after the key/restore outbox recovery has
    made the mutation durable. The audit event named after the operation_id
    is the durable fact: a ``success`` event rebuilds the original 201
    response, while a ``rejected`` event rebuilds the exact 403/404/409
    terminal (its state, error body and audit projection) from the recorded
    action/key_id and the current tenant state. Returns
    ``(http_status, response)``.
    """
    op_id = record.operation_id
    details = record.details or {}
    kind = details.get("kind")
    tenant_id = record.tenant_id
    operator_id = record.operator_id

    def error(status: int, message: str):
        return status, {"error": message, "operation_id": op_id}

    if event.outcome == audit_mod.OUTCOME_REJECTED:
        action = event.action
        terminal = details.get("terminal")
        # A batch rotation is AUTHORIZED as rotate even though its audit
        # action is batch_rotate; map back for the legacy no-terminal policy
        # reconstruction below.
        policy_action = (
            audit_mod.ACTION_ROTATE
            if action == audit_mod.ACTION_BATCH_ROTATE
            else action
        )

        def message_for(status: int) -> str:
            if status == 403:
                return "action not permitted by policy"
            if status == 409:
                if kind == "restore":
                    return "backup target already contains this data"
                if kind == "migrate":
                    return "key is already managed by the ready provider"
                if kind in ("rotate", "batch_rotate"):
                    return "current_version does not match expected_version"
                return "key_id already exists for this tenant"
            if kind == "restore":
                return "tenant backup not found"
            return "key not found"

        # The original terminal status is persisted with the event: replay it
        # verbatim, so a policy change or a state change after the crash can
        # never turn a 403 into a 404/409 or vice versa.
        if terminal in (403, 404, 409):
            return error(terminal, message_for(terminal))

        # Older records without the stashed terminal: infer once from the
        # durable action and the current state.
        # A policy denial outranks existence: it is reconstructed whenever the
        # tenant's policy currently rejects this operator/action. The durable
        # event names the target key when one existed, so key-scoped rules
        # apply exactly as they did at the original decision.
        replay_key_id = event.key_id
        if replay_key_id is None and kind in ("rotate", "import", "migrate"):
            replay_key_id = details.get("key_id")
        if replay_key_id is not None and not is_valid_key_id(replay_key_id):
            replay_key_id = None
        try:
            if kind == "batch_rotate":
                # The batch was authorized item-by-item under rotate; deny is
                # reconstructed when any item's current policy denies it.
                policy_allowed = all(
                    policy_store.is_allowed(
                        tenant_id, policy_action, operator_id,
                        one.get("key_id")
                        if is_valid_key_id(one.get("key_id"))
                        else None,
                    )
                    for one in details.get("items", [])
                )
            else:
                policy_allowed = policy_store.is_allowed(
                    tenant_id, policy_action, operator_id, replay_key_id
                )
        except PolicyStoreUnavailable:
            # A corrupt policy document must not block crash recovery: fall
            # through to the durable state-based reconstruction below rather
            # than guessing a 403.
            policy_allowed = True
        if not policy_allowed:
            return error(403, message_for(403))
        if kind == "restore":
            # A same-tenant conflict is reconstructed when any key from the
            # write set now belongs to the tenant, a restored policy exists,
            # or (empty bundle) the persistent empty-restore marker is on
            # disk. Every other rejection (in-bundle tenant mismatch, foreign
            # occupation) replays as 404. Restore events always carry
            # key_id null.
            for key_id in details.get("key_ids", []):
                raw = store.read_raw(key_id)
                if raw is not None and raw.tenant_id == tenant_id:
                    return error(409, message_for(409))
            if details.get("policy_restored") and policy_store.get(
                tenant_id
            ) is not None:
                return error(409, message_for(409))
            digest = hashlib.sha256(tenant_id.encode("utf-8")).hexdigest()
            marker = os.path.join(
                store.data_dir, "restore-empty-" + digest + ".json"
            )
            if os.path.exists(marker):
                return error(409, message_for(409))
            return error(404, message_for(404))
        if kind == "import":
            key_id = event.key_id or details.get("key_id")
            raw = store.read_raw(key_id) if is_valid_key_id(key_id) else None
            if raw is not None and raw.tenant_id == tenant_id:
                return error(409, message_for(409))
            return error(404, message_for(404))
        # rotate (and any unknown shape): a rejected rotate means the key was
        # unknown or foreign at commit time and no version was appended.
        return error(404, message_for(404))

    if kind == "migrate":
        key_id = event.key_id or details.get("key_id")
        key = store.get(key_id, tenant_id)
        if key is not None:
            return (
                200,
                {
                    "key_id": key_id,
                    "provider_id": key.current.provider_id,
                    "versions": sorted(ver.version for ver in key.versions),
                    "operation_id": op_id,
                },
            )
        return 200, {"operation_id": op_id}
    if kind == "rotate":
        key_id = event.key_id or details.get("key_id")
        key = store.get(key_id, tenant_id)
        if key is not None:
            # The committed version is the one whose creation time equals the
            # event timestamp; fall back to the current pointer.
            ver = None
            for candidate in key.versions:
                if candidate.created_at == event.timestamp:
                    ver = candidate
                    break
            if ver is None:
                ver = key.current
            return (
                201,
                {
                    "key_id": key_id,
                    "version": ver.version,
                    "algorithm": ver.algorithm,
                    "public_key": ver.public_key,
                    "operation_id": op_id,
                },
            )
    if kind == "batch_rotate":
        # The batch's single event carries key_id null; the request-order
        # item set is durable in details. Rebuild each item's committed
        # version (the one minted at the event timestamp, else the current
        # pointer). A key that is no longer readable makes the projection fall
        # back to operation_id-only rather than fabricating a version.
        result_items = []
        complete = True
        for one in details.get("items", []):
            key_id = one.get("key_id")
            key = (
                store.get(key_id, tenant_id)
                if is_valid_key_id(key_id)
                else None
            )
            if key is None:
                complete = False
                break
            ver = None
            for candidate in key.versions:
                if candidate.created_at == event.timestamp:
                    ver = candidate
                    break
            if ver is None:
                ver = key.current
            result_items.append(
                {
                    "key_id": key_id,
                    "version": ver.version,
                    "algorithm": ver.algorithm,
                    "public_key": ver.public_key,
                }
            )
        if complete:
            return 201, {"items": result_items, "operation_id": op_id}
    if kind in ("create", "import"):
        key_id = event.key_id or details.get("key_id")
        key = store.get(key_id, tenant_id)
        if key is not None:
            if kind == "create":
                # Replay the ORIGINAL version-1 facts even if the key was
                # rotated later: later rotation can never change a create
                # replay's algorithm or public key.
                version = key.get_version(1)
                if version is None:
                    return 201, {"operation_id": op_id}
                body = {
                    "key_id": key_id,
                    "algorithm": version.algorithm,
                    "public_key": version.public_key,
                    "operation_id": op_id,
                }
                return 201, body
            body = key.to_create_response()
            body["operation_id"] = op_id
            return 201, body
    if kind == "restore":
        return (
            201,
            {
                "tenant_id": tenant_id,
                "key_ids": details.get("key_ids", []),
                "policy_restored": details.get("policy_restored", False),
                "operation_id": op_id,
            },
        )
    # Cannot rebuild the projection; the mutation did commit, so keep it
    # succeeded with an operation_id-only body rather than pending forever.
    return 201, {"operation_id": op_id}


def serve(host: str, port: int, data_dir: str) -> None:
    """Run the HTTP server until interrupted."""
    audit_log = AuditLog(data_dir)
    # Key-store and restore outbox recovery run first (constructors), so a
    # half-committed mutation's files/handles are settled before the
    # operation store resolves the pending operation that wrapped it.
    store = KeyStore(data_dir, audit_log)
    policy_store = PolicyStore(data_dir, audit_log)
    coordinator = restore_mod.RestoreCoordinator(store, policy_store)
    operation_store = OperationStore(data_dir, audit_log)
    # The artifact mirrors settle next (after the outbox recovery): a
    # consistent mirror is cleaned, a fully rolled-back attempt's mirror is
    # dropped, and an unprovable scene keeps both its evidence and its
    # operation pending for a later open.
    from .artifacts import ArtifactStore

    artifact_store = ArtifactStore(data_dir, store, audit_log)
    artifact_store.settle_pending(operation_store)
    operation_store.recover_pending(
        lambda record, event: _resolve_committed_operation(
            store, policy_store, record, event
        ),
        is_parked=artifact_store.is_parked,
    )
    httpd = ThreadingHTTPServer(
        (host, port),
        make_handler(
            store, policy_store, coordinator, operation_store, artifact_store
        ),
    )
    httpd.daemon_threads = True
    try:
        httpd.serve_forever()

    response = result.get("response")
    if http_status is None and response is None:
        return True
    if not isinstance(response, dict):
        return False
    kind = descriptor.get("kind")
    tenant_id = descriptor.get("tenant_id")
    write_set = descriptor.get("write_set") or []
    # A creating mutation stages a 201; an in-place/non-creating operation
    # (read-only encrypt, whole-key migrate) stages a 200.
    allowed_status = 200 if kind in _STATUS_200_KINDS else 201
    if http_status != allowed_status:
        return False
    if kind in ("create", "rotate", "import"):
        key_id = write_set[0] if write_set else None
        if response.get("key_id") != key_id:
            return False
        key = self.key_store._read_record(self.key_store._path_for(key_id))
        if key is None or key.tenant_id != tenant_id:
            return False
        if kind == "rotate":
            version = response.get("version")
            if not isinstance(version, int) or key.get_version(version) is None:
                return False
        else:
            # create/import: the replay must preserve the ORIGINAL
            # algorithm and public key (version 1), even if the key was
            # rotated later.
            version = key.get_version(1)
            if version is None:
                return False
            if response.get("algorithm") != version.algorithm:
                return False
            if response.get("public_key") != version.public_key:
                return False
    elif kind == "migrate":
        key_id = write_set[0] if write_set else None
        if response.get("key_id") != key_id:
            return False
        target = response.get("provider_id")
        if not isinstance(target, str) or not target:
            return False
        versions = response.get("versions")
        if (
            not isinstance(versions, list)
            or not versions
            or not all(
                isinstance(number, int) and not isinstance(number, bool)
                and number > 0
                for number in versions
            )
            or versions != sorted(versions)
            or len(set(versions)) != len(versions)
        ):
            return False
        key = self.key_store._read_record(self.key_store._path_for(key_id))
        if key is None or key.tenant_id != tenant_id:
            return False
        if [ver.version for ver in key.versions] != versions:
            return False
        # Every version must actually be rebound to the ready provider.
        if any(ver.provider_id != target for ver in key.versions):
            return False
    elif kind == "batch_rotate":
        items = response.get("items")
        if not isinstance(items, list):
            return False
        response_keys = set()
        for item in items:
            if not isinstance(item, dict):
                return False
            key_id = item.get("key_id")
            if not _is_key_id(key_id):
                return False
            response_keys.add(key_id)
            key = self.key_store._read_record(
                self.key_store._path_for(key_id)
            )
            if key is None or key.tenant_id != tenant_id:
                return False
            version = item.get("version")
            if not isinstance(version, int) or key.get_version(version) is None:
                return False
        if response_keys != set(write_set):
            return False
    elif kind == "encrypt":
        # The read-only encrypt creates nothing: the key must still exist
        # for the mirror's tenant and the staged envelope must name that
        # same key and one of its existing versions. The envelope bytes
        # themselves are opaque -- only structural metadata is checked.
        from . import envelope as envelope_mod

        key_id = write_set[0] if write_set else None
        if response.get("format") != envelope_mod.FORMAT:
            return False
        if response.get("operation_id") != descriptor.get("operation_id"):
            return False
        token = response.get("envelope")
        if not isinstance(token, str) or not token:
            return False
        try:
            opened = envelope_mod.decode_envelope(token)
        except Exception:
            return False
        if opened.key_id != key_id:
            return False
        key = self.key_store._read_record(self.key_store._path_for(key_id))
        if key is None or key.tenant_id != tenant_id:
            return False
        if key.get_version(opened.version) is None:
            return False
    elif kind == "restore":
        key_ids = response.get("key_ids")
        if not isinstance(key_ids, list) or sorted(key_ids) != sorted(
            write_set
        ):
            return False
        if response.get("policy_restored") != bool(descriptor.get("policy")):
            return False
        for key_id in write_set:
            key = self.key_store._read_record(
                self.key_store._path_for(key_id)
            )
            if key is None or key.tenant_id != tenant_id:
                return False
    return True

def _committed_state_verified(self, descriptor: dict) -> bool:
    """Verify the committed write set and every surviving reference.

    Every write-set key file must exist, belong to the mirror's tenant,
    carry no unresolved pending marker of this operation and own every
    (provider_id, handle) the mirror recorded; a restore that carried a
    policy leaves the tenant's committed policy document, and an empty
    restore leaves its finalized (event-cleared) marker. The provision
    journal and a batch snapshot are post-commit housekeeping and must
    already be gone. Finally every surviving on-disk reference must be
    cross-consistent with the mirror (a missing/corrupt/duplicate/extra
    reference keeps the mirror for the next open).
    """
    if not self._descriptor_consistent(descriptor, allow_undescribed=False):
        return False
    operation_id = descriptor["operation_id"]
    journal_id = descriptor.get("journal") or operation_id
    if os.path.exists(self.key_store._provision_path(journal_id)):
        return False
    if descriptor.get("snapshot") and os.path.exists(
        self.key_store._batch_snapshot_path(descriptor["snapshot"])
    ):
        return False
    kind = descriptor.get("kind")
    tenant_id = descriptor.get("tenant_id")
    owned = set()
    for key_id in descriptor.get("write_set", []):
        record = self.key_store._read_record(self.key_store._path_for(key_id))
        if record is None or record.tenant_id != tenant_id:
            return False
        marker = getattr(record, "pending_event", None)
        if isinstance(marker, dict) and self._marker_event_id(
            marker
        ) == operation_id:
            return False
        for ver in record.versions:
            owned.add((ver.provider_id, ver.handle))
    expected = {
        (entry.get("provider_id"), entry.get("handle"))
        for entry in descriptor.get("handles", [])
        if isinstance(entry, dict)
    }
    if not expected.issubset(owned):
        return False
    if kind == "restore" and not self._committed_restore_extras_verified(
        descriptor
    ):
        return False
    if not self._surviving_artifacts_consistent(descriptor):
        return False
    return True

def _committed_restore_extras_verified(self, descriptor: dict) -> bool:
    """Committed restore policy document and empty-restore marker checks."""
    tenant_id = descriptor.get("tenant_id")
    if descriptor.get("policy"):
        doc = self._read_policy_doc(self._policy_doc_path(tenant_id))
        if doc is None:
            return False
        owner, pending = doc
        if owner != tenant_id:
            return False
        if isinstance(pending, dict) and self._marker_event_id(
            pending
        ) == descriptor.get("operation_id"):
            return False
    if not descriptor.get("write_set") and not descriptor.get("policy"):
        # An empty restore commits only its persistent marker: it must
        # survive, be finalized (event cleared) and name this tenant.
        path = descriptor.get("empty_marker")
        if not isinstance(path, str) or not os.path.exists(path):
            return False
        try:
            with open(path, "r", encoding="utf-8") as fh:
                marker = json.load(fh)
        except (OSError, ValueError):
            return False
        if not isinstance(marker, dict) or not marker.get("_empty"):
            return False
        if marker.get("tenant_id") != tenant_id or marker.get("event") is not None:
            return False
    return True

def _policy_doc_path(self, tenant_id: str) -> str:
    # Mirror PolicyStore._path_for WITHOUT constructing a PolicyStore: its
    # constructor runs outbox recovery, which a read-only verification must
    # never trigger as a side effect.
    digest = hashlib.sha256(tenant_id.encode("utf-8")).hexdigest()
    return os.path.join(self.data_dir, "policies", digest + ".json")

def _read_policy_doc(self, path: str):
    """Read (tenant_id, pending_event) from a policy file, side-effect free.

    Rules are not validated here -- only the owning tenant and the pending
    marker are cross-checked -- so this never instantiates PolicyStore (and
    never runs its startup outbox recovery). Returns None when the file is
    absent or unreadable.
    """
    try:
        with open(path, "r", encoding="utf-8") as fh:
            doc = json.load(fh)
    except (OSError, ValueError):
        return None
    if not isinstance(doc, dict):
        return None
    return doc.get("tenant_id"), doc.get("pending_event")

# -- surviving-artifact cross-validation -------------------------------
def _surviving_artifacts_consistent(self, descriptor: dict) -> bool:
    """Whether every surviving on-disk reference cross-agrees.

    Returns False when a surviving reference is missing, corrupt,
    duplicated or carries more/fewer facts than the mirror; the caller
    then keeps the whole evidence set. Absence of an artifact the attempt
    legitimately removed is fine.
    """
    try:
