def do_POST(self) -> None:
    parts = urlsplit(self.path)
    path = parts.path
    operator = self._operator()
    if operator is None:
        return
    self._operator_id = operator
    try:
        if path == "/v1/keys":
            self._create_key(operator, parts)
            return

        rotate_match = _ROTATE_PATH_RE.match(path)
        if rotate_match is not None:
            self._rotate_key(rotate_match.group(1), parts, operator)
            return

        revoke_match = _REVOKE_PATH_RE.match(path)
        if revoke_match is not None:
            self._revoke_key(revoke_match.group(1), parts, operator)
            return

        version_revoke_match = _VERSION_REVOKE_PATH_RE.match(path)
        if version_revoke_match is not None:
            self._revoke_version(
                version_revoke_match.group(1),
                version_revoke_match.group(2),
                parts, operator,
            )
            return

        export_match = _EXPORT_PATH_RE.match(path)
        if export_match is not None:
            self._export_key(export_match.group(1), parts, operator)
            return

        encrypt_match = _ENCRYPT_PATH_RE.match(path)
        if encrypt_match is not None:
            self._encrypt_key(encrypt_match.group(1), parts, operator)
            return

        migrate_match = _MIGRATE_PATH_RE.match(path)
        if migrate_match is not None:
            self._migrate_key(migrate_match.group(1), parts, operator)
            return

        decrypt_match = _DECRYPT_PATH_RE.match(path)
        if decrypt_match is not None:
            self._decrypt_key(decrypt_match.group(1), parts, operator)
            return

        wrap_key_match = _WRAP_KEY_PATH_RE.match(path)
        if wrap_key_match is not None:
            self._wrap_data_key(
                wrap_key_match.group(1), parts, operator
            )
            return

        unwrap_key_match = _UNWRAP_KEY_PATH_RE.match(path)
        if unwrap_key_match is not None:
            self._unwrap_data_key(
                unwrap_key_match.group(1), parts, operator
            )
            return

        rewrap_match = _REWRAP_PATH_RE.match(path)
        if rewrap_match is not None:
            self._rewrap_key(rewrap_match.group(1), parts, operator)
            return

        sign_match = _SIGN_PATH_RE.match(path)
        if sign_match is not None:
            self._sign_key(sign_match.group(1), parts, operator)
            return

        verify_match = _VERIFY_PATH_RE.match(path)
        if verify_match is not None:
            self._verify_key(verify_match.group(1), parts, operator)
            return

        if path == _IMPORT_PATH:
            self._import_key(parts, operator)
            return

        if path == _IMPORT_PREFLIGHT_PATH:
            self._import_preflight(parts, operator)
            return

        if path == _BATCH_ROTATE_PATH:
            self._batch_rotate_keys(parts, operator)
            return

        if path == _BACKUP_PATH:
            self._backup_tenant(parts, operator)
            return

        if path == _BACKUP_VERIFY_PATH:
            self._backup_verify(parts, operator)
            return

        if path == _RESTORE_PATH:
            self._restore_tenant(parts, operator)
            return

        if path == _RESTORE_PREFLIGHT_PATH:
            self._restore_preflight(parts, operator)
            return

        if path == _POLICY_CHECK_PATH:
            self._check_policy(parts)
            return

        if path == _PROVIDER_RECONNECT_PATH:
            self._provider_reconnect()
            return

        if path == _PROVIDER_SWITCHOVER_PATH:
            self._provider_switchover()
            return
    except ProviderInvalidMaterial as exc:
        self._provider_invalid_material(exc)
        return
    except ProviderUnavailable as exc:
        self._provider_unavailable(exc)
        return
    except PolicyStoreUnavailable:
        self._send_json(
            500, {"error": "policy store is unavailable"}
        )
        return
    except LedgerError as exc:
        self._server_error(exc)
        return

    self._send_json(404, {"error": "not found"})

def _key_locks_deadline(self, key_id: str, deadline) -> Iterator[None]:
    """Take the in-process and fcntl locks against one shared deadline."""
    with self._timed_inproc(key_id, deadline), self._file_lock(
        key_id, deadline
    ):
        yield

@contextmanager
def key_locks(self, key_id: str, timeout: Optional[float] = None) -> Iterator[None]:
    """Acquire the in-process and cross-process locks for one key_id.

    With a finite ``timeout`` both locks share one deadline and a wait
    beyond it raises :class:`LockTimeout` with nothing held.
    """
    if timeout is None:
        with self._key_lock(key_id), self._file_lock(key_id):
            yield
    else:
        with self._key_locks_deadline(
            key_id, time.monotonic() + timeout
        ):
            yield

@contextmanager
def multi_key_locks(
    self, key_ids, timeout: Optional[float] = None
) -> Iterator[None]:
    """Acquire the per-key locks for many key_ids, in sorted order.

    A fixed acquisition order keeps this deadlock-free against the
    restore transaction, which also takes its key locks sorted. With a
    finite ``timeout`` the whole acquisition shares one deadline.
    """
    deadline = None if timeout is None else time.monotonic() + timeout
    acquired = []
    try:
        for key_id in sorted(set(key_ids)):
            if deadline is None:
                lock_cm = self.key_locks(key_id)
            else:
                lock_cm = self._key_locks_deadline(key_id, deadline)
            lock_cm.__enter__()
            acquired.append(lock_cm)
        yield
    finally:
        for lock_cm in reversed(acquired):
            lock_cm.__exit__(None, None, None)

